      cpp: `#include <iostream>\n#include <vector>\n#include <stack>\nusing namespace std;\nint main() {\n    int n; if (!(cin >> n)) return 0;\n    vector<long long> a(n), res(n, 0);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && a[st.top()] < a[i]) {\n            res[st.top()] = a[i];\n            st.pop();\n        }\n        st.push(i);\n    }\n    for (int i = 0; i < n; i++) cout << res[i] << (i == n - 1 ? "" : " ");\n    cout << "\\n";\n    return 0;\n}`,
