async function seed() {
  try {
    console.log(`Connecting to MongoDB for LinkedList problems...`);
    await mongoose.connect(MONGO_URI);
    console.log(`Connected successfully!`);

    let insertedCount = 0;
    let updatedCount = 0;

    for (let i = 0; i < LINKEDLIST_50_PROBLEMS.length; i++) {
      const prob = LINKEDLIST_50_PROBLEMS[i];
      try {
        const existing = await CodingProblem.findOne({ title: prob.title });
        if (existing) {
          await CodingProblem.findByIdAndUpdate(existing._id, prob, { runValidators: true });
          updatedCount++;
        } else {
          await CodingProblem.create(prob);
          insertedCount++;
        }
      } catch (err) {
        console.error(`Failed on problem #${i + 1}: "${prob.title}"`, err.message);
        throw err;
      }
    }

    console.log(
      `LinkedList seeding complete! Inserted: ${insertedCount}, Updated: ${updatedCount}, Total: ${LINKEDLIST_50_PROBLEMS.length}`
    );
    process.exit(0);
  } catch (err) {
    console.error("LinkedList seeding error:", err);
    process.exit(1);
  }
}

seed();
